/**
 * A figure's card with its bio: the role and the date line, the lead, the
 * "don't confuse" note, and its years and end (lives.ts). A figure with no bio keeps its own text. Fields that
 * only repeat the card's head or lead ("role and context", "in the material")
 * are dropped, and so are the notebook's raw notes on ties, which the card's
 * list of ties shows drawn from the tree.
 */
const REPEATS=new Set(["תפקיד והקשר","בחומר הנלמד","קשרים"]);
export function withBio<T extends {id:string;kind:string;subtitle:string;date:string;summary:string;fields:{label:string;text:string}[];life?:{lived:string;active:string;death:string}}>(node:T):T{
 if(node.kind!=="person")return node;
 const b=BIOS[node.id],life=LIVES[node.id];
 const kept=node.fields.filter(f=>f.text.trim()&&f.text!==node.summary&&!REPEATS.has(f.label)&&!(b?.trap&&f.label==="לא להתבלבל"));
 if(!b)return {...node,life,fields:kept};
 return {...node,life,subtitle:b.role,date:b.when,summary:b.who,fields:[...(b.trap?[{label:"לא להתבלבל",text:b.trap}]:[]),...kept]};
}
